"""
For task-2bb261a3: 
Transformation rule: Shift all rows down by 1, fill top row with foreground color.
- If row 0 is not uniform, foreground = grid[0][0]
- If row 0 is uniform, foreground = the other color in the grid
"""

def transform(grid):
    if not grid or not grid[0]:
        return grid

    row0 = grid[0]
    if len(set(row0)) > 1:
        fg_color = row0[0]
    else:
        all_colors = set()
        for row in grid:
            all_colors.update(row)
        bg_color = row0[0]
        other_colors = [c for c in all_colors if c != bg_color]
        if other_colors:
            fg_color = other_colors[0]
        else:
            fg_color = bg_color

    rows = len(grid)
    cols = len(grid[0])
    new_grid = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        if r == 0:
            new_grid[r] = [fg_color] * cols
        else:
            new_grid[r] = [grid[r-1][c] for c in range(cols)]

    return new_grid
